  if (!states.has(name)) {
    const entries = new Map(name === oldObjectName ? [["record", record]] : []);
    states.set(name, {
      storage: {
        get: async (key) => entries.get(key),
        put: async (key, value) => void entries.set(key, value),
        delete: async (key) => entries.delete(key)
      }
    });
  }
  return states.get(name);
};
